mapper.select:
SELECT A.CUST_ID AS custId , A.CUST_NM AS custNm , A.BIZ_REG_NO AS bizRegNo , A.CEO_NM AS ceoNm , A.PIC_NM AS picNm , A.PIC_CONTACT AS picTel , A.PIC_EMAIL AS picEmail , A.CUST_GRADE AS custGrade , A.CUST_ADDR AS custAddr , A.CUST_REMARK AS custRemark , IF(B.FAV_ID IS NOT NULL, 'Y', 'N') AS favYn FROM TB_CUSTOMER A LEFT JOIN TB_FAVORITE B ON A.CUST_ID = B.TARGET_ID AND B.TARGET_TYPE = 'CUSTOMER' AND B.EMP_ID = #{loginId} WHERE A.DEL_YN = 'N'
AND CUST_NM LIKE CONCAT('%', #{searchKeyword}, '%')
ORDER BY favYn DESC, A.CUST_ID DESC LIMIT #{recordCountPerPage} OFFSET #{firstIndex}

mapper.insert:
INSERT INTO TB_CUSTOMER (
    CUST_NM, BIZ_REG_NO, CEO_NM, PIC_NM, PIC_CONTACT, PIC_EMAIL, CUST_ADDR, CUST_REMARK, CUST_GRADE
) VALUES (
    #{custNm}, #{bizRegNo}, #{ceoNm}, #{picNm}, #{picTel}, #{picEmail}, #{custAddr}, #{custRemark}, #{custGrade}
)

mapper.update:
UPDATE TB_CUSTOMER SET
      CUST_NM = #{custNm}
    , BIZ_REG_NO = #{bizRegNo}
    , CEO_NM = #{ceoNm}
    , PIC_NM = #{picNm}
    , PIC_CONTACT = #{picTel}
    , PIC_EMAIL = #{picEmail}
    , CUST_ADDR = #{custAddr}
    , CUST_REMARK = #{custRemark}
    , LAST_UPDUSR_ID = #{lastUpdusrId}
    , CUST_GRADE = #{custGrade}
WHERE CUST_ID = #{custId}

UPDATE TB_CUSTOMER SET 
      DEL_YN = 'Y'
    , LAST_UPDUSR_ID = #{lastUpdusrId}
WHERE CUST_ID = #{custId}

mapper.select:
SELECT COUNT(*)
FROM TB_FAVORITE
WHERE EMP_ID = #{loginId}
  AND TARGET_TYPE = #{targetType}
  AND TARGET_ID = #{targetId}

mapper.delete:
DELETE FROM TB_FAVORITE
WHERE EMP_ID = #{loginId}
  AND TARGET_TYPE = #{targetType}
  AND TARGET_ID = #{targetId}
